# The sheet's rates, by grade.
# Seen as of a date (?asOf=), as it stood then; see sheet.AsOf.
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
  govern: [ transaction ]
# Set a grade's rate. Validate first so a bad grade or percent is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.rate.RecordRateSet
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
  govern: [ transaction ]
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A grade's rate on a sheet: a percent with two decimals, in force from `from` (null: from the beginning of time)
 *  through `to` (null: with no end). */
public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.rate;

/** Body of a rate change: the grade (A, B or C), the percent, the from-date and to-date (yyyy-mm-dd,
 *  blank for none) and who makes the change. */
public record RateRequest(String grade, String pct, String from, String to, String user) {
}
package net.officefloor.hq.app.rate;

/** A rate as the screen sees it: `pct` with two decimals, `from` and `to` as yyyy-mm-dd or null when it has none. */
public record RateResponse(String grade, String pct, String from, String to) {
    public static RateResponse from(Rate rate) {
        return new RateResponse(rate.grade(), rate.pct().toPlainString(),
                rate.from() != null ? rate.from().toString() : null,
                rate.to() != null ? rate.to().toString() : null);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rates for each grade of each sheet; a grade has at most one per from-date (or none). */
@Repository
public class Rates {

    private final JdbcTemplate jdbc;

    public Rates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate on the sheet, by grade, then by from-date (the one with none first). */
    public List<Rate> onSheet(String sheetId) {
        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date FROM rate WHERE sheet_id = ? ORDER BY grade, from_key",
                (rs, i) -> {
                    Date from = rs.getDate("from_date");
                    Date to = rs.getDate("to_date");
                    return new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("pct"),
                            from != null ? from.toLocalDate() : null, to != null ? to.toLocalDate() : null);
                },
                sheetId);
    }

    /** The grade's rate in force on `date`: the one with the latest from-date on or before it, or
     *  null when there is none or that one's to-date is before `date`. */
    public BigDecimal pct(String sheetId, String grade, LocalDate date) {
        return jdbc.query("SELECT pct, to_date FROM rate WHERE sheet_id = ? AND grade = ? AND from_key <= ?"
                + " ORDER BY from_key DESC LIMIT 1",
                (rs, i) -> {
                    Date to = rs.getDate("to_date");
                    return to != null && to.toLocalDate().isBefore(date) ? null : rs.getBigDecimal("pct");
                }, sheetId, grade, Date.valueOf(date))
                .stream().filter(p -> p != null).findFirst().orElse(null);
    }

    /** Set the grade's rate from its from-date, replacing the one it had for that from-date. */
    public void save(Rate rate) {
        Date from = rate.from() != null ? Date.valueOf(rate.from()) : null;
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                rate.sheetId(), rate.grade(), from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), from, rate.to() != null ? Date.valueOf(rate.to()) : null);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the rate is saved, so a refused change writes no audit line. */
public class RecordRateSet {
    public void record(@Val RateRequest request, @Val Rate rate, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + request.user()
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() != null ? " from=" + rate.from() : "")
                + (rate.to() != null ? " to=" + rate.to() : ""));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRate {
    public void respond(@Val Rate rate, ObjectResponse<RateResponse> response) {
        response.send(RateResponse.from(rate));
    }
}
package net.officefloor.hq.app.rate;

import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithRates {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Rates rates, AsOf asOfSheet,
            ObjectResponse<List<RateResponse>> response) throws InvalidSheetRequestException {
        response.send(asOfSheet.view(sheetId, asOf,
                () -> rates.onSheet(sheetId).stream().map(RateResponse::from).toList()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;

public class SaveRate {
    public void save(@Val Rate rate, Rates rates) {
        rates.save(rate);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** A percent: 0.00 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

