# Add a holiday. Validate first so a bad or repeated date is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.holiday.ValidateHoliday
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.holiday.SaveHoliday
  govern: [ transaction ]
  next: record
# Audit only once the holiday is saved: a refused one writes no line.
record:
  class: net.officefloor.hq.app.holiday.RecordHolidayAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.holiday.RespondWithHoliday
  govern: [ transaction ]
EOF

